package tr.gov.kocaeli.sehir.inspection.api;
import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import tr.gov.kocaeli.sehir.inspection.application.InspectionService;import java.util.*;
@RestController @RequestMapping("/api/v1/inspections")public class InspectionController{private final InspectionService service;public InspectionController(InspectionService service){this.service=service;}@PostMapping("/request/{requestId}")@PreAuthorize("hasAnyRole('SYSTEM_ADMIN','UNIT_MANAGER','TECHNICAL_REVIEWER','FIELD_PERSONNEL')")Map<String,Object>create(@PathVariable UUID requestId,@RequestBody InspectionService.Create body){return service.create(requestId,body);}@PostMapping("/{id}/complete")@PreAuthorize("hasAnyRole('SYSTEM_ADMIN','TECHNICAL_REVIEWER','FIELD_PERSONNEL')")Map<String,Object>complete(@PathVariable UUID id,@RequestBody InspectionService.Complete body){return service.complete(id,body);}@GetMapping("/{id}")Map<String,Object>get(@PathVariable UUID id){return service.get(id);}}

